import subprocess
import os
import glob
import time
def task_func(test_dir):
    if not isinstance(test_dir, str):
        raise TypeError("Invalid directory type")
    if test_dir == "" or not os.path.isdir(test_dir):
        raise OSError("Invalid directory path")
    pattern = os.path.join(test_dir, "*.py")
    scripts = glob.glob(pattern)
    results = {}
    for script in scripts:
        start_time = time.time()
        try:
            subprocess.run(["python", script], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except Exception:
            pass
        end_time = time.time()
        script_name = os.path.basename(script)
        results[script_name] = end_time - start_time
    return results

