import subprocess
import os
import json
from datetime import datetime
def task_func(script_name='backup.sh', log_file='/home/user/backup_log.json'):
    script_path = os.path.abspath(script_name)
    if not os.path.exists(script_path):
        raise FileNotFoundError("Script file does not exist")
    start_time = datetime.now()
    start_str = start_time.strftime('%Y-%m-%d %H:%M:%S')
    try:
        result = subprocess.run(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        exit_status = result.returncode
    except Exception as e:
        raise RuntimeError(f"Error executing script: {e}")
    end_time = datetime.now()
    end_str = end_time.strftime('%Y-%m-%d %H:%M:%S')
    log_data = {
        'start_time': start_str,
        'end_time': end_str,
        'exit_status': exit_status
    }
    try:
        if os.path.exists(log_file):
            try:
                with open(log_file, 'r') as f:
                    existing = json.load(f)
            except Exception:
                existing = []
        else:
            existing = []
        if isinstance(existing, list):
            existing.append(log_data)
            to_write = existing
        else:
            to_write = [existing, log_data]
        with open(log_file, 'w') as f:
            json.dump(to_write, f)
    except Exception:
        pass
    return log_data

