import subprocess
import csv
import glob
import random
import os
def task_func(file):
    if not isinstance(file, str):
        return []
    if not os.path.isfile(file):
        return []
    if not file.lower().endswith('.csv'):
        return []
    base_dir = os.path.dirname(os.path.abspath(file))
    prefix = os.path.join(base_dir, 'split_')
    try:
        subprocess.run(['split', '-d', '-a', '3', '--additional-suffix=.csv', file, prefix], check=True)
    except Exception:
        return []
    split_files = sorted(glob.glob(prefix + '*.csv'))
    if not split_files:
        return []
    try:
        for f in split_files:
            try:
                with open(f, newline='', encoding='utf-8') as infile:
                    reader = list(csv.reader(infile))
            except UnicodeDecodeError:
                with open(f, newline='') as infile:
                    reader = list(csv.reader(infile))
            if not reader:
                continue
            header = reader[0]
            rows = reader[1:]
            random.shuffle(rows)
            try:
                with open(f, 'w', newline='', encoding='utf-8') as outfile:
                    writer = csv.writer(outfile)
                    writer.writerow(header)
                    writer.writerows(rows)
            except UnicodeEncodeError:
                with open(f, 'w', newline='') as outfile:
                    writer = csv.writer(outfile)
                    writer.writerow(header)
                    writer.writerows(rows)
    except Exception:
        return []
    return split_files

