import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not os.path.exists(script_path) or not os.path.isfile(script_path):
        raise OSError("Invalid script_path")
    proc = subprocess.Popen(["bash", script_path])
    p = psutil.Process(proc.pid)
    cpu_usage = 0.0
    mem_usage = 0
    start_time = time.time()
    last_time = start_time
    last_cpu_times = p.cpu_times()
    while True:
        if time.time() - start_time > timeout:
            if proc.poll() is None:
                try:
                    proc.terminate()
                except Exception:
                    pass
            break
        if proc.poll() is not None:
            try:
                p_status = p.status()
            except psutil.NoSuchProcess:
                break
            if p_status == psutil.STATUS_ZOMBIE:
                break
        try:
            current_cpu_times = p.cpu_times()
            now = time.time()
            delta_time = now - last_time
            if delta_time > 0:
                delta_cpu = (current_cpu_times.user + current_cpu_times.system) - (last_cpu_times.user + last_cpu_times.system)
                if delta_cpu > 0:
                    cpu_percent = (delta_cpu / delta_time) * 100.0
                    cpu_usage += cpu_percent
            last_cpu_times = current_cpu_times
            last_time = now
            mem_info = p.memory_info()
            mem_usage += mem_info.rss
        except psutil.NoSuchProcess:
            break
        except psutil.ZombieProcess:
            break
        time.sleep(0.1)
    try:
        if proc.poll() is None:
            proc.terminate()
    except Exception:
        pass
    return {"CPU Usage": cpu_usage, "Memory Usage": mem_usage}

