import subprocess
import psutil
import time
import os
def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if not os.path.exists(script_path) or not os.path.isfile(script_path):
        raise OSError("Invalid script path")
    proc = subprocess.Popen(['bash', script_path])
    p = psutil.Process(proc.pid)
    cpu_usage = 0.0
    mem_usage = 0
    start_time = time.time()
    try:
        while True:
            if time.time() - start_time > timeout:
                if proc.poll() is None:
                    proc.terminate()
                    try:
                        proc.wait(5)
                    except subprocess.TimeoutExpired:
                        proc.kill()
                break
            if not psutil.pid_exists(proc.pid):
                break
            try:
                if p.status() == psutil.STATUS_ZOMBIE:
                    break
                cpu = p.cpu_percent(interval=0.1)
                mem = p.memory_info().rss
                cpu_usage += cpu
                mem_usage += mem
            except (psutil.NoSuchProcess, psutil.ZombieProcess):
                break
            if proc.poll() is not None:
                break
    finally:
        if proc.poll() is None:
            try:
                proc.terminate()
                proc.wait(timeout=5)
            except Exception:
                try:
                    proc.kill()
                except Exception:
                    pass
    return {'CPU Usage': cpu_usage, 'Memory Usage': mem_usage}

